// Build microflow summary
const catalysts = $('Get Catalyst Scores').first().json;
const divergences = $('Get Divergence Flags').first().json;

const scores = catalysts?.scores || [];
const flags = divergences?.flags || [];

// Find suppress_short flags
const suppressShorts = flags.filter(f => f.divergence_signal === 'SUPPRESS_SHORT');
const macroDominants = flags.filter(f => f.divergence_signal === 'MACRO_DOMINANT');

// Top catalyst scores
const topCatalysts = scores.sort((a,b) => b.catalyst_score - a.catalyst_score).slice(0, 5);

let alertLevel = 'NORMAL';
let alertColor = '🟢';
if (suppressShorts.length > 0) { alertLevel = 'SUPPRESS_SHORT'; alertColor = '🔴'; }
else if (macroDominants.length > 0) { alertLevel = 'MACRO_DOMINANT'; alertColor = '🟡'; }

let summary = `${alertColor} Microflow Monitor\n`;
scores.forEach(s => {
  const flag = flags.find(f => f.instrument === s.instrument);
  const signal = flag ? flag.divergence_signal : 'NEUTRAL';
  summary += `${s.instrument}: catalyst=${s.catalyst_score?.toFixed(0)} [${signal}]\n`;
});
if (suppressShorts.length > 0) {
  summary += `\n⚠ SUPPRESS_SHORT active for: ${suppressShorts.map(s => s.instrument).join(', ')}`;
  summary += `\n   No short signals for these instruments`;
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    top_catalysts: topCatalysts,
    all_scores: scores,
    divergence_flags: flags,
    suppress_short_instruments: suppressShorts.map(s => s.instrument),
    macro_dominant_instruments: macroDominants.map(s => s.instrument),
    alert_level: alertLevel,
    summary,
    is_alert: suppressShorts.length > 0
  }
}];
